final class History {
    private final java.util.ArrayDeque<String> recent = new java.util.ArrayDeque<>();
    void remember(String id) {
        recent.addLast(id);
        if (recent.size() > 100) recent.removeFirst();
    }
}

final class Counter {
    private int value;
    synchronized void increment() { value++; }
    synchronized int value() { return value; }
}

class Counter {
    private var value = 0
    @Synchronized fun increment() { value++ }
    @Synchronized fun value(): Int = value
}

